import { detectInstalledAgents, listMcpAgentIds, resolveAddMcpAgentId, uniqueAgentIds } from "./agents.js";
import { mcpUnsupportedReason } from "./install.js";
import { detectProjectAgents } from "add-mcp";
//#region src/mcp/targets.ts
function mcpInstallableAgents(scope) {
	return listMcpAgentIds().filter((id) => mcpUnsupportedReason(id, scope) === void 0);
}
async function detectMcpAgents(options) {
	const detected = options.scope === "project" ? detectProjectAgents(options.cwd) : await detectInstalledAgents();
	return uniqueAgentIds(detected).filter((id) => mcpUnsupportedReason(id, options.scope) === void 0);
}
function resolveInstallTargets(options) {
	const requested = uniqueAgentIds(options.agents.map(resolveAddMcpAgentId));
	const install = [];
	const skipped = [];
	for (const agent of requested) {
		const error = mcpUnsupportedReason(agent, options.scope);
		if (error) skipped.push({
			agent,
			error
		});
		else install.push(agent);
	}
	if (install.length === 0) {
		const details = skipped.map((row) => row.error).join(" ");
		throw new Error(details || `None of the selected agents can install the Neon MCP server. Supported agents: ${mcpInstallableAgents(options.scope).join(", ")}`);
	}
	return {
		install,
		skipped
	};
}
//#endregion
export { detectMcpAgents, mcpInstallableAgents, resolveInstallTargets };
